import { CommonModule } from '@angular/common';
import { Component } from '@angular/core';
import { FormBuilder, FormGroup, FormsModule, ReactiveFormsModule, Validators } from '@angular/forms';
import { ToastService } from '../../../common/toast.service';
import { environment } from '../../../../environments/environment';
import { HttpClient } from '@angular/common/http';
declare var bootstrap: any;
@Component({
  selector: 'app-state-events',
  standalone: true,
  imports: [CommonModule, FormsModule, ReactiveFormsModule],
  templateUrl: './state-events.component.html',
  styleUrl: './state-events.component.scss'
})
export class StateEventsComponent {
      users: any[] = [];
      pageSize: number = 15;
      currentPage: number = 1;
      searchText: string = '';
      selectedNewsId: number | null = null;
    
      addNewsEventForm: FormGroup;
      editNewsEventForm: FormGroup;
      selectedImages: { [key: string]: any } = {};
      showPreview: { [key: string]: boolean } = {};
    
      pagination = {
        total: 0,
        page: 1,
        limit: 15
      };
    
      constructor(
        private http: HttpClient,
        private fb: FormBuilder,
        private toastService: ToastService
      ) {
        this.addNewsEventForm = this.fb.group({
          title: ['', Validators.required],
          description: ['', Validators.required],
          newsLink: [''],
          eventType: ['event'],
          eventDate: ['', Validators.required]
        });
    
        this.editNewsEventForm = this.fb.group({
          title: ['', Validators.required],
          description: ['', Validators.required],
          newsLink: [''],
          eventDate: ['', Validators.required]
        });
      }
    
      ngOnInit(): void {
        this.loadNewsEvents();
      }
    
      // -------------------- Load News --------------------
      loadNewsEvents(page: number = 1, limit: number = 15) {
        this.toastService.showToast('Loading events...', 'info');
    
        let url = `${environment.apiUrl}/latest-news-events?page=${page}&limit=${limit}&eventType=event&isActive=true`;
        if (this.searchText.trim()) {
          url += `&title=${encodeURIComponent(this.searchText.trim())}`;
        }
    
        this.http.get<any>(url).subscribe({
          next: (res) => {
            this.users = res.data?.data || [];
                this.toastService.showToast('Event loaded successfully', 'success');
            this.pagination.total = res.data?.pagination?.total || 0;
            this.pagination.limit = limit;
            this.pagination.page = page;
          },
          error: (err) => {
            console.error('Error fetching events:', err);
            this.toastService.showToast('Failed to load events.', 'danger');
          }
        });
      }
    
      onSearchKeyup(): void {
        this.loadNewsEvents(1, this.pageSize);
      }
    
      // -------------------- Pagination --------------------
      get totalPages(): number {
        return Math.ceil(this.pagination.total / this.pagination.limit);
      }
    
      changePage(page: number) {
        if (page >= 1 && page <= this.totalPages) {
          this.currentPage = page;
          this.loadNewsEvents(this.currentPage, this.pageSize);
        }
      }
    
      goPrevious() { this.changePage(this.currentPage - 1); }
      goNext() { this.changePage(this.currentPage + 1); }
    
      onPageSizeChange(event: any) {
        this.pageSize = +event.target.value;
        this.currentPage = 1;
        this.loadNewsEvents(this.currentPage, this.pageSize);
      }
    
      // -------------------- Image Handling --------------------
      onImageSelected(event: any, key: string) {
        const file = event.target.files[0];
        if (file) {
          this.selectedImages[key] = URL.createObjectURL(file);
          this.selectedImages[key + 'File'] = file;
        }
      }
    
      togglePreview(key: string) {
        this.showPreview[key] = !this.showPreview[key];
      }
    
      openBannerInNewTab(base64Image: string) {
        const newWindow = window.open();
        if (newWindow) {
          newWindow.document.write(`<img src="${base64Image}" style="width:100%"/>`);
          newWindow.document.title = 'News/Event Banner';
        }
      }
    
      // -------------------- Add News --------------------
      openAddNewsDrawer() {
        const drawerEl = document.getElementById('addNewsEventDrawer');
        if (drawerEl) {
          const bsDrawer = new bootstrap.Offcanvas(drawerEl);
          bsDrawer.show();
        }
      }
    
    onAddNewsEventSubmit() {
      if (this.addNewsEventForm.invalid || !this.selectedImages['bannerImageFile']) {
        this.toastService.showToast('Please fill all required fields', 'danger');
        return;
      }
    
      this.toastService.showToast('Adding event...', 'info');
    
      const reader = new FileReader();
      reader.onload = () => {
        const payload: any = {
          title: this.addNewsEventForm.value.title?.trim(),
          description: this.addNewsEventForm.value.description?.trim(),
          bannerImage: reader.result as string,
          eventType: 'event',
          eventDate: this.addNewsEventForm.value.eventDate
        };
    
        // Add newsLink only if it's provided
        const newsLink = this.addNewsEventForm.value.newsLink?.trim();
        if (newsLink) {
          payload.newsLink = newsLink;
        }
    
        this.http.post(`${environment.apiUrl}/latest-news-events`, payload).subscribe({
          next: () => {
            this.toastService.showToast('Event added successfully!', 'success');
            this.addNewsEventForm.reset();
            this.selectedImages['bannerImage'] = null;
            this.selectedImages['bannerImageFile'] = null;
            this.loadNewsEvents();
    
            const drawer = document.getElementById('addNewsEventDrawer');
            if (drawer) bootstrap.Offcanvas.getInstance(drawer)?.hide();
          },
          error: (err) => {
            console.error(err);
            this.toastService.showToast('Failed to add Event.', 'danger');
          }
        });
      };
    
      reader.readAsDataURL(this.selectedImages['bannerImageFile']);
    }
    
    
      // -------------------- Edit News --------------------
      editNews(user: any) {
        this.selectedNewsId = user.id;
        this.editNewsEventForm.patchValue({
          title: user.title || '',
          description: user.description || '',
          newsLink: user.newsLink || '',
          eventDate: user.eventDate ? new Date(user.eventDate).toISOString().split('T')[0] : ''
        });
    
        this.selectedImages['bannerImage'] = user.bannerImage || null;
        this.selectedImages['bannerImageFile'] = null;
    
        const offcanvasEl = document.getElementById('editNewsDrawer');
        if (offcanvasEl) {
          const bsOffcanvas = new bootstrap.Offcanvas(offcanvasEl);
          bsOffcanvas.show();
        }
      }
    
    onEditNewsSubmit() {
      if (!this.selectedNewsId || this.editNewsEventForm.invalid) return;
    
      this.toastService.showToast('Updating event...', 'info');
    
      const payload: any = {
        title: this.editNewsEventForm.value.title?.trim(),
        description: this.editNewsEventForm.value.description?.trim(),
        eventDate: this.editNewsEventForm.value.eventDate
      };
    
      // Handle newsLink: send value if exists, otherwise send null
      const newsLink = this.editNewsEventForm.value.newsLink?.trim();
      payload.newsLink = newsLink !== '' ? newsLink : null;
    
      if (this.selectedImages['bannerImageFile']) {
        const reader = new FileReader();
        reader.onload = () => {
          payload.bannerImage = reader.result as string;
          this.updateNews(payload);
        };
        reader.readAsDataURL(this.selectedImages['bannerImageFile']);
      } else {
        this.updateNews(payload);
      }
    }
    
    
      private updateNews(payload: any) {
        this.http.patch(`${environment.apiUrl}/latest-news-events/${this.selectedNewsId}`, payload)
          .subscribe({
            next: () => {
              this.toastService.showToast('Event updated successfully!', 'success');
              this.loadNewsEvents(this.currentPage, this.pageSize);
              this.selectedNewsId = null;
              this.editNewsEventForm.reset();
              this.selectedImages['bannerImage'] = null;
              this.selectedImages['bannerImageFile'] = null;
              this.showPreview['bannerImage'] = false;
              bootstrap.Offcanvas.getInstance(document.getElementById('aboutusDrawer'))?.hide();
            },
            error: (err) => {
              console.error('Error updating Event:', err);
              this.toastService.showToast('Failed to update News.', 'danger');
            }
          });
      }
    
      // -------------------- Delete News --------------------
      deleteNews(newsId: number) {
        if (!confirm('Are you sure you want to delete this Event?')) return;
    
        this.toastService.showToast('Deleting event...', 'info');
    
        this.http.delete(`${environment.apiUrl}/latest-news-events/${newsId}`).subscribe({
          next: () => {
            this.toastService.showToast('Event deleted successfully!', 'success');
            this.loadNewsEvents(this.currentPage, this.pageSize);
          },
          error: (err) => {
            this.toastService.showToast('Failed to delete Event', 'danger');
          }
        });
      }
}
